export const EMPATHY_ACTIVITIES = [
// FASE A — FONDASI / KONKRET (1-20): apa itu empati
{n:1,type:"mcq",micro:"Apa itu empati",q:"'Empati' adalah...",options:["Kemampuan memahami & ikut merasakan apa yang dirasakan orang lain, seolah dari sudut pandang mereka","Selalu setuju dengan semua orang","Merasa kasihan pada orang dari kejauhan tanpa memahami"],answer:0,explain:"Empati berarti 'masuk' ke pengalaman orang lain untuk memahami perasaan mereka, bukan sekadar menilai dari luar.",hint:"Memahami & ikut merasakan dari sudut mereka, atau selalu setuju / kasihan dari jauh?"},
{n:2,type:"mcq",micro:"Empati vs simpati",q:"Beda 'empati' dengan 'simpati':",options:["Simpati selalu lebih baik daripada empati","Empati = ikut merasakan & memahami dari sisi mereka ('aku paham betapa sakitnya itu'); simpati = merasa kasihan dari luar ('duh, kasihan ya')","Keduanya sama persis"],answer:1,explain:"Simpati sering terasa seperti 'aku di atas, kamu di bawah'. Empati lebih seperti 'aku di sampingmu, mencoba memahami'.",hint:"Ikut merasakan dari sisi mereka vs kasihan dari luar, atau sama saja?"},
{n:3,type:"mcq",micro:"Empati bukan berarti setuju",q:"Berempati pada seseorang yang pendapatnya berbeda dengan kita berarti...",options:["Harus langsung setuju dengan mereka","Berarti kita kalah dalam perdebatan","Berusaha memahami kenapa mereka merasa/berpikir begitu, tanpa harus mengubah pendapat kita sendiri"],answer:2,explain:"Empati adalah alat memahami, bukan tanda menyerah. Kita bisa mengerti perasaan seseorang & tetap tidak setuju dengan pandangannya.",hint:"Memahami tanpa harus setuju, atau harus setuju / berarti kalah?"},
{n:4,type:"mcq",micro:"Empati dimulai dari memperhatikan",q:"Langkah pertama berempati pada seseorang:",options:["Benar-benar memperhatikan mereka, kata-kata, nada suara, ekspresi, & apa yang mungkin sedang mereka alami","Langsung memberi nasihat tentang apa yang harus mereka lakukan","Menceritakan pengalamanmu sendiri yang mirip"],answer:0,explain:"Empati butuh perhatian penuh dulu. Nasihat & cerita sendiri (kalau perlu) datang belakangan, setelah kita benar-benar memahami.",hint:"Memperhatikan dulu, atau langsung nasihat / cerita sendiri?"},
{n:5,type:"mcq",micro:"Empati & mendengarkan",q:"Mendengarkan dengan empati berarti mendengarkan untuk...",options:["Menemukan cara membuktikan kita lebih tahu","Memahami perasaan & kebutuhan orang, bukan hanya menunggu giliran bicara atau menyiapkan bantahan","Mencari kesalahan dalam apa yang mereka katakan"],answer:1,explain:"Mendengarkan empatik fokus pada 'apa yang sebenarnya dirasakan & dibutuhkan orang ini?', bukan pada respons kita.",hint:"Memahami perasaan & kebutuhan, atau menunggu giliran / mencari kesalahan?"},
{n:6,type:"mcq",micro:"Validasi perasaan",q:"'Memvalidasi' perasaan seseorang berarti...",options:["Menyetujui semua yang mereka lakukan","Menyuruh mereka berhenti merasakan itu","Mengakui bahwa perasaan mereka masuk akal & wajar untuk mereka rasakan ('wajar kamu kecewa soal itu'), tanpa harus setuju dengan semua tindakan mereka"],answer:2,explain:"Validasi meredakan kesepian & membuat orang merasa dimengerti. 'Kamu berhak merasa seperti itu' sering sangat membantu.",hint:"Mengakui perasaan masuk akal, atau menyetujui semua tindakan / menyuruh berhenti merasa?"},
{n:7,type:"mcq",micro:"Tidak buru-buru memberi solusi",q:"Saat seseorang bercerita tentang masalahnya, sering yang paling membantu di awal adalah...",options:["Mendengarkan & menunjukkan bahwa kita memahami, bukan langsung memberi daftar solusi","Segera memberi tahu apa yang harus mereka lakukan","Menceritakan bahwa masalah kita lebih besar"],answer:0,explain:"Banyak orang butuh merasa didengar dulu sebelum siap memikirkan solusi. Bertanya 'kamu butuh didengar atau butuh saran?' juga membantu.",hint:"Dengarkan & tunjukkan pengertian dulu, atau langsung solusi / bandingkan masalah?"},
{n:8,type:"mcq",micro:"Isyarat emosi",q:"Petunjuk tentang perasaan seseorang bisa datang dari...",options:["Kita tidak bisa tahu perasaan orang lain sama sekali","Kata-kata, nada suara, ekspresi wajah, bahasa tubuh, & perubahan perilaku (jadi lebih diam, mudah tersinggung, dll)","Hanya dari kata-kata yang mereka ucapkan langsung"],answer:1,explain:"Sering perasaan yang tidak diucapkan terlihat dari perubahan lain. Memperhatikan berbagai isyarat membantu kita lebih peka.",hint:"Berbagai isyarat, atau hanya kata-kata / tidak bisa tahu sama sekali?"},
{n:9,type:"order",micro:"Menanggapi teman yang sedih",q:"Urutkan langkah menanggapi teman yang sedang bercerita bahwa ia sedih.",items:["Berikan perhatian penuh (letakkan HP, hadapkan tubuh ke mereka, dengarkan)","Akui & validasi perasaannya ('kedengarannya berat ya', 'wajar kamu sedih')","Tanyakan apa yang mereka butuhkan (didengar? ditemani? saran?)","Tanggapi sesuai kebutuhan mereka, bukan sesuai asumsimu"],answer:[0,1,2,3],explain:"Perhatian penuh → validasi → tanya kebutuhan → tanggapi sesuai itu. Menanyakan kebutuhan mencegah kita memberi hal yang salah (mis. saran saat mereka hanya ingin didengar).",hint:"Menanyakan apa yang mereka butuhkan dilakukan sebelum atau sesudah menanggapi?"},
{n:10,type:"mcq",micro:"Empati bisa dilatih",q:"Kemampuan berempati...",options:["Adalah bakat tetap, dimiliki sejak lahir atau tidak sama sekali","Tidak bisa berkembang setelah masa kanak-kanak","Bisa dilatih & berkembang seiring waktu dengan latihan (memperhatikan, mendengarkan, membayangkan pengalaman orang lain)"],answer:2,explain:"Meski sebagian orang mungkin lebih mudah berempati secara alami, semua orang bisa memperkuat kemampuan ini lewat latihan sadar.",hint:"Bisa dilatih & berkembang, atau bakat tetap?"},
{n:11,type:"tf",micro:"Empati bermanfaat untuk semua",q:"Benar atau Salah: Empati membantu membangun hubungan yang lebih baik, menyelesaikan konflik, & membuat orang di sekitar kita merasa lebih dihargai & didukung.",answer:true,explain:"Empati adalah dasar dari hubungan yang sehat, kerja sama yang baik, & komunitas yang saling peduli.",hint:"Bermanfaat luas untuk hubungan, atau hanya soal 'baik hati'?"},
{n:12,type:"tf",micro:"Empati berarti menanggung semua perasaan orang?",q:"Benar atau Salah: Berempati berarti kita wajib menanggung sepenuhnya semua perasaan berat semua orang di sekitar kita sampai kita sendiri kewalahan.",answer:false,explain:"Sebaliknya, empati yang sehat mencakup menjaga batas diri. Kita bisa peduli & memahami tanpa menyerap semua emosi orang lain sampai kelelahan sendiri.",hint:"Wajib menanggung semua sampai kewalahan, atau bisa peduli sambil menjaga batas?"},
{n:13,type:"mcq",micro:"Empati pada orang yang berbeda dari kita",q:"Berempati pada seseorang yang latar belakang/pengalamannya sangat berbeda dari kita membutuhkan...",options:["Kemauan mendengar & bertanya tentang pengalaman mereka, & menerima bahwa kita mungkin tidak sepenuhnya paham tapi tetap bisa peduli","Menganggap pengalaman mereka pasti sama dengan kita","Menyerah karena 'kita tidak akan pernah mengerti'"],answer:0,explain:"Empati lintas perbedaan butuh kerendahan hati (aku mungkin tidak sepenuhnya paham) & kemauan belajar, bukan asumsi atau menyerah.",hint:"Kemauan mendengar & menerima keterbatasan, atau berasumsi sama / menyerah?"},
{n:14,type:"mcq",micro:"Empati vs kasihan yang merendahkan",q:"Beda empati dari 'kasihan' yang bisa terasa merendahkan:",options:["Kasihan selalu lebih tulus daripada empati","Empati memperlakukan orang sebagai setara yang sedang mengalami kesulitan; kasihan yang merendahkan menempatkan mereka sebagai 'lebih rendah' atau 'objek belas kasihan'","Keduanya sama & sama baiknya"],answer:1,explain:"'Aku turut prihatin & aku di sini bersamamu' terasa berbeda dari 'ya ampun, kasihan banget sih kamu'.",hint:"Memperlakukan sebagai setara, atau menempatkan sebagai lebih rendah?"},
{n:15,type:"mcq",micro:"Empati & kata-kata yang membantu",q:"Kalimat yang menunjukkan empati saat teman kesulitan:",options:["'Ah, gitu doang. Move on aja.'","'Harusnya kamu nggak usah kepikiran.'","'Kedengarannya sulit banget. Aku di sini kalau kamu mau cerita atau butuh sesuatu.'"],answer:2,explain:"Kalimat empatik mengakui kesulitan & menawarkan kehadiran, bukan meremehkan atau menyuruh berhenti merasa.",hint:"Mengakui & menawarkan kehadiran, atau meremehkan / menyuruh berhenti merasa?"},
{n:16,type:"tf",micro:"Empati diperlukan bahkan saat kita sibuk",q:"Benar atau Salah: Tanggapan empatik harus selalu berupa percakapan panjang berjam-jam; tanggapan singkat tidak ada artinya.",answer:false,explain:"Sebaliknya, empati bukan soal durasi tapi kehadiran & perhatian yang tulus. Tanggapan singkat (kontak mata, mengangguk, 'aku dengar kok, nanti kita ngobrol lebih ya') pun bisa berarti banyak.",hint:"Tanggapan singkat pun bisa berarti, atau harus selalu lama?"},
{n:17,type:"mcq",micro:"Empati saat orang sedang marah pada kita",q:"Kalau seseorang marah pada kita, berusaha memahami perasaan mereka (tanpa membenarkan cara mereka bila kasar) bisa...",options:["Membantu meredakan situasi & memahami apa yang sebenarnya jadi masalah, lebih dari sekadar membela diri langsung","Berarti kita mengalah pada semua tuntutan mereka","Tidak pernah membantu dalam konflik"],answer:0,explain:"Sering di balik kemarahan ada rasa terluka atau kebutuhan yang tidak terpenuhi. Memahaminya (sambil tetap menjaga batas) membuka jalan penyelesaian.",hint:"Membantu meredakan & memahami akar masalah, atau berarti mengalah pada semua?"},
{n:18,type:"mcq",micro:"Empati untuk diri sendiri",q:"'Empati pada diri sendiri' (self-compassion) berarti...",options:["Tidak pernah mengakui kesalahan sendiri","Memperlakukan diri dengan pengertian & kebaikan saat sedang kesulitan, seperti kita memperlakukan teman yang kita sayangi","Selalu memaafkan diri untuk semua hal tanpa tanggung jawab"],answer:1,explain:"Kita sering lebih keras pada diri sendiri daripada pada orang lain. Memberi diri kebaikan yang sama (tanpa menghindari tanggung jawab) itu sehat.",hint:"Pengertian & kebaikan pada diri saat kesulitan, atau maaf tanpa tanggung jawab?"},
{n:19,type:"mcq",micro:"Empati & rasa ingin tahu",q:"Rasa ingin tahu yang tulus tentang pengalaman orang lain ('kayak gimana sih rasanya buat kamu?') membantu empati karena...",options:["Membuat orang merasa diinterogasi","Tidak berhubungan dengan empati","Membuka pintu untuk benar-benar memahami, bukan hanya berasumsi dari sudut pandang kita sendiri"],answer:2,explain:"Bertanya dengan tulus (bukan menghakimi atau mengarahkan) adalah cara menghormati bahwa pengalaman orang lain mungkin berbeda dari bayangan kita.",hint:"Membuka pintu untuk memahami, atau membuat diinterogasi / tak berhubungan?"},
{n:20,type:"open",micro:"Latihan mendengarkan dengan empati",q:"Pilih satu percakapan nyata di mana seseorang bercerita tentang perasaan atau kesulitan mereka (bisa yang sudah terjadi atau yang akan kamu lakukan). Refleksikan/rencanakan: (a) bagaimana kamu memberi/akan memberi perhatian penuh, (b) satu kalimat validasi yang kamu ucapkan/akan ucapkan, (c) bagaimana kamu menahan/akan menahan diri dari langsung memberi solusi, (d) bagaimana kamu mengetahui apa yang sebenarnya mereka butuhkan.",sample:"Percakapan: sahabatku, Nadia, bercerita bahwa ia merasa tertekan karena orang tuanya menuntut nilai sempurna & ia takut mengecewakan mereka. (a) Perhatian penuh: aku meletakkan HP, menghadapkan tubuhku ke arahnya, & benar-benar mendengarkan tanpa memikirkan apa yang akan kukatakan selanjutnya; aku menatapnya & sesekali mengangguk supaya ia tahu aku mendengar. (b) Kalimat validasi: 'Kedengarannya berat banget ya, ngerasa kayak nggak pernah cukup meskipun sudah berusaha. Wajar sih kamu ngerasa tertekan.' (c) Menahan diri dari solusi: awalnya aku ingin langsung bilang 'coba ngomong ke orang tua kamu' atau 'nilai bukan segalanya kok', tapi aku sadar itu bisa terasa seperti meremehkan atau menggampangkan. Jadi aku menahan diri & memberi ruang untuknya bercerita lebih dulu. (d) Mengetahui kebutuhannya: setelah ia bercerita cukup panjang, aku bertanya 'Kamu lagi butuh didengerin aja, atau pengen mikir bareng gimana caranya?' Ia bilang untuk sekarang ia hanya butuh didengar & tidak merasa sendirian. Jadi aku fokus menemaninya & tidak memberi saran, cukup bilang 'aku di sini, kapan pun kamu butuh cerita lagi.'",explain:"Jawaban baik: cara memberi perhatian penuh yang konkret (bukan sekadar 'mendengarkan'), kalimat validasi yang benar-benar mengakui perasaan spesifiknya, kesadaran akan godaan memberi solusi cepat & kenapa itu bisa kurang membantu, & cara nyata mengetahui kebutuhannya (menanyakan langsung: didengar atau butuh saran?).",hint:"Bagian (c) & (d) sering terlewat, banyak orang otomatis memberi solusi padahal yang dibutuhkan sering hanya didengar; menanyakan langsung menghindari salah menanggapi."},

// FASE B — PEMAHAMAN (21-40): membaca emosi, merespons, batas
{n:21,type:"classify",micro:"Respons empatik vs kurang empatik",q:"Kelompokkan tiap respons ke 'Empatik' atau 'Kurang empatik' saat teman bercerita ia gagal ujian & sangat kecewa.",items:["'Wah, pasti rasanya nggak enak banget ya setelah belajar keras.'","'Ah, cuma satu ujian. Nggak usah lebay.'","'Aku di sini kalau kamu mau cerita lebih.'","'Harusnya kamu belajar lebih giat dari kemarin.'"],groups:["Empatik","Kurang empatik"],answer:{"Empatik":["'Wah, pasti rasanya nggak enak banget ya setelah belajar keras.'","'Aku di sini kalau kamu mau cerita lebih.'"],"Kurang empatik":["'Ah, cuma satu ujian. Nggak usah lebay.'","'Harusnya kamu belajar lebih giat dari kemarin.'"]},explain:"Empatik: mengakui perasaan & menawarkan kehadiran. Kurang empatik: meremehkan perasaan atau langsung menyalahkan.",hint:"Mengakui & menemani, atau meremehkan / menyalahkan?"},
{n:22,type:"mcq",micro:"Empati kognitif & afektif",q:"'Empati kognitif' (memahami apa yang orang pikirkan/rasakan) & 'empati afektif' (ikut merasakannya) sering...",options:["Bekerja bersama; memahami membantu kita ikut merasakan, & ikut merasakan mendorong kita memahami lebih dalam","Bertentangan & tidak bisa ada bersamaan","Hanya salah satu yang bisa dilatih"],answer:0,explain:"Keduanya adalah bagian dari empati yang utuh. Ada juga 'empati welas asih' (compassionate empathy), yang mendorong kita untuk membantu.",hint:"Bekerja bersama, atau bertentangan?"},
{n:23,type:"mcq",micro:"Empati welas asih (compassionate)",q:"'Empati welas asih' menambahkan satu unsur pada memahami & ikut merasakan, yaitu...",options:["Menjaga jarak agar tidak terpengaruh","Dorongan untuk membantu atau mendukung, bukan hanya larut dalam perasaan orang lain","Menjadi sedih tanpa melakukan apa pun"],answer:1,explain:"Empati welas asih menyeimbangkan 'aku memahami & peduli' dengan 'aku ingin & bisa membantu', tanpa harus tenggelam dalam kesedihan.",hint:"Menambah dorongan untuk membantu, atau larut tanpa tindakan / menjaga jarak?"},
{n:24,type:"mcq",micro:"Membaca emosi yang tidak diucapkan",q:"Kalau seseorang bilang 'aku nggak apa-apa kok' tapi terlihat murung & menghindari kontak mata, respons yang peka:",options:["Percaya sepenuhnya bahwa mereka 'nggak apa-apa' & lupakan","Memaksa mereka mengakui perasaan sekarang juga","Beri ruang, & sampaikan bahwa kamu ada untuk mereka kapan pun ('oke, tapi kalau kamu mau cerita, aku di sini ya'), tanpa memaksa"],answer:2,explain:"Kadang orang belum siap bercerita. Menawarkan kehadiran tanpa memaksa menghormati kesiapan mereka sambil menunjukkan kepedulian.",hint:"Beri ruang & tawarkan kehadiran, atau percaya penuh / paksa mengakui?"},
{n:25,type:"mcq",micro:"Empati dalam konflik",q:"Saat berselisih dengan seseorang, sesekali mencoba menyatakan ulang sisi mereka dengan adil ('jadi menurut kamu...') membantu karena...",options:["Menunjukkan bahwa kamu benar-benar mendengarkan, & sering membuat mereka lebih terbuka mendengar sisimu juga","Berarti kamu mengaku salah","Membuang waktu dalam perdebatan"],answer:0,explain:"Orang lebih mau mendengar kita setelah merasa didengar. Empati dalam konflik bisa mengubah 'perang' jadi 'percakapan'.",hint:"Menunjukkan mendengarkan & membuka dialog, atau mengaku salah / buang waktu?"},
{n:26,type:"mcq",micro:"Empati bukan 'memperbaiki' perasaan orang",q:"Kalau temanmu sedih & kamu tidak bisa 'menghilangkan' kesedihannya, kamu tetap bisa membantu dengan...",options:["Menyerah & menjauh karena 'tidak ada yang bisa kulakukan'","Menemani, mendengarkan, & membiarkan mereka tahu bahwa mereka tidak sendirian, kehadiran itu sendiri berharga","Merasa gagal karena tidak bisa membuat mereka bahagia lagi"],answer:1,explain:"Kita tidak selalu bisa menyelesaikan masalah atau menghapus perasaan orang lain. Kehadiran yang tulus sering sudah sangat berarti.",hint:"Menemani & menunjukkan mereka tak sendirian, atau merasa gagal / menjauh?"},
{n:27,type:"tf",micro:"Empati punya batas yang sehat",q:"Benar atau Salah: Empati yang benar berarti tanpa batas, kita harus selalu mengorbankan kesejahteraan & kebutuhan kita sendiri demi orang lain.",answer:false,explain:"Sebaliknya, empati yang sehat mencakup menjaga batas diri. Kita bisa peduli & mendukung tanpa mengorbankan diri sepenuhnya; empati tanpa batas menyebabkan 'kelelahan empati'.",hint:"Punya batas sehat, atau harus tanpa batas?"},
{n:28,type:"tf",micro:"Empati vs dimanfaatkan",q:"Benar atau Salah: Berempati berarti membiarkan orang lain memperlakukan kita dengan buruk atau memanfaatkan kebaikan kita terus-menerus, karena menetapkan batas berarti tidak peduli.",answer:false,explain:"Sebaliknya, empati & ketegasan bisa berjalan bersama. 'Aku paham kamu sedang kesulitan, tapi aku tidak bisa terus meminjamkan uang' adalah empati dengan batas.",hint:"Bisa berempati & tetap tegas, atau empati berarti selalu mengalah?"},
{n:29,type:"mcq",micro:"Empati untuk orang yang menyakiti kita",q:"Berusaha memahami kenapa seseorang menyakiti kita (mis. mereka juga sedang terluka) dapat membantu kita...",options:["Selalu langsung memaafkan & melupakan","Berarti perbuatan mereka jadi tidak apa-apa","Memahami situasi & memutuskan respons yang tepat, tanpa berarti membenarkan perbuatan mereka atau harus memaafkan segera"],answer:2,explain:"Memahami sebab tidak sama dengan membenarkan. Empati bisa membantu kita merespons dengan lebih bijak, sambil tetap menjaga diri.",hint:"Memahami tanpa membenarkan, atau harus langsung maaf / berarti tak apa-apa?"},
{n:30,type:"order",micro:"Menanggapi teman yang marah pada kita",q:"Urutkan langkah menanggapi teman yang marah pada kita dengan empati.",items:["Tetap tenang & dengarkan apa yang membuat mereka marah tanpa langsung membela diri","Coba pahami perasaan & kebutuhan di balik kemarahannya (merasa dikhianati? tidak dihargai?)","Akui bagian yang memang kesalahan kita bila ada, & sampaikan sisi kita dengan tenang setelahnya","Cari solusi bersama, atau bila situasinya tidak sehat (mereka kasar), tetapkan batas dengan jelas"],answer:[0,1,2,3],explain:"Dengarkan → pahami perasaannya → akui & sampaikan sisi kita → cari solusi / tetapkan batas. Memahami dulu sebelum membela diri membuka jalan penyelesaian.",hint:"Membela diri / menyampaikan sisi kita dilakukan sebelum atau sesudah mendengarkan & memahami perasaan mereka?"},
{n:31,type:"mcq",micro:"Empati & tidak menghakimi",q:"Empati yang sehat berusaha menahan diri dari langsung menghakimi ('harusnya kamu nggak begitu') karena...",options:["Penghakiman cepat menutup pintu pemahaman & membuat orang merasa tidak aman untuk jujur","Penghakiman selalu membantu orang menjadi lebih baik","Kita harus selalu menyembunyikan pendapat kita"],answer:0,explain:"Menahan penghakiman bukan berarti tidak punya pendapat, tapi menunda menilai sampai kita benar-benar memahami. Orang lebih terbuka saat tidak merasa dihakimi.",hint:"Menghakimi menutup pemahaman, atau selalu membantu?"},
{n:32,type:"tf",micro:"Merasakan emosi orang lain bisa melelahkan",q:"Benar atau Salah: Ikut merasakan emosi berat orang lain tidak pernah melelahkan; kalau kita merasa perlu merawat diri setelahnya, itu tanda kita tidak benar-benar peduli.",answer:false,explain:"Sebaliknya, 'kelelahan empati' nyata, terutama bila sering & intens. Mengisi kembali energi setelah mendukung orang lain justru membuat kita bisa terus peduli dengan tulus.",hint:"Bisa melelahkan & butuh merawat diri, atau tak berpengaruh?"},
{n:33,type:"mcq",micro:"Empati lewat cerita & pengalaman orang",q:"Membaca kisah, menonton film, atau mendengar pengalaman hidup orang yang berbeda dari kita bisa...",options:["Tidak ada hubungannya dengan empati","Memperluas kemampuan berempati dengan membantu kita membayangkan pengalaman yang tidak pernah kita alami sendiri","Membuat kita jadi terlalu emosional & lemah"],answer:1,explain:"Kisah adalah 'latihan empati', memberi kita jendela ke kehidupan yang berbeda & melatih kita memahami perasaan yang asing.",hint:"Memperluas empati, atau membuat lemah / tak berhubungan?"},
{n:34,type:"mcq",micro:"Empati vs 'membajak' cerita orang",q:"Saat teman bercerita tentang kesulitannya, langsung menimpali dengan 'aku juga pernah begitu, malah lebih parah...' berpotensi...",options:["Selalu membantu karena menunjukkan kita mengerti","Tidak berpengaruh pada bagaimana mereka merasa","Mengalihkan fokus dari mereka ke kita, membuat mereka merasa kurang didengar; sebaiknya tunggu & fokus pada cerita mereka dulu"],answer:2,explain:"Berbagi pengalaman serupa bisa membantu, tapi timing-nya penting. Kalau terlalu cepat, terasa seperti 'membajak' momen mereka. Selesaikan mendengarkan mereka dulu.",hint:"Bisa mengalihkan fokus, atau selalu membantu / tak berpengaruh?"},
{n:35,type:"mcq",micro:"Empati & keberagaman perasaan",q:"Kalau seseorang bereaksi terhadap sesuatu dengan emosi yang jauh lebih kuat dari yang kamu duga, sikap empatik:",options:["Menerima bahwa sesuatu yang kecil bagimu bisa besar bagi mereka karena pengalaman & konteks mereka berbeda","Menganggap mereka berlebihan & tidak masuk akal","Menyuruh mereka 'biasa aja'"],answer:0,explain:"Kita tidak selalu tahu apa yang sedang ditanggung orang lain atau apa arti sesuatu bagi mereka. Menerima perbedaan reaksi adalah bentuk empati.",hint:"Menerima artinya berbeda bagi tiap orang, atau menganggap berlebihan / menyuruh 'biasa aja'?"},
{n:36,type:"mcq",micro:"Empati saat kita sendiri sedang kesulitan",q:"Kalau kamu sendiri sedang beremosi berat & seseorang datang minta didengar, sikap yang jujur & sehat:",options:["Mengabaikan mereka sepenuhnya tanpa penjelasan","Bisa mengatakan dengan baik 'aku pengen dengerin kamu, tapi aku juga lagi berat banget hari ini, bisa nanti ya?' atau mendengarkan sebisamu sambil jujur soal kondisimu","Selalu memaksakan diri mendengarkan meski kewalahan"],answer:1,explain:"Empati tidak berarti selalu tersedia tanpa syarat. Jujur tentang kapasitas kita adalah bentuk menghormati diri sendiri & orang lain.",hint:"Jujur soal kapasitasmu, atau memaksakan diri / mengabaikan tanpa kabar?"},
{n:37,type:"tf",micro:"Empati membangun kepercayaan",q:"Benar atau Salah: Menunjukkan bahwa kita berusaha memahami perasaan orang lain tidak berpengaruh pada seberapa mereka mempercayai atau merasa aman dengan kita.",answer:false,explain:"Sebaliknya, orang cenderung lebih percaya & merasa aman dengan seseorang yang berusaha memahami perasaan mereka, bukan yang selalu menghakimi atau meremehkan. Empati adalah fondasi utama membangun kepercayaan.",hint:"Membangun kepercayaan, atau tak berpengaruh?"},
{n:38,type:"mcq",micro:"Empati & tindakan",q:"Empati yang lengkap sering menuntun pada...",options:["Hanya perasaan tanpa pernah melakukan apa pun","Menanggung semua masalah orang lain sendirian","Tindakan yang membantu (menemani, menawarkan bantuan konkret, membela yang diperlakukan tidak adil), sesuai kemampuan kita"],answer:2,explain:"Empati yang berhenti di perasaan saja kurang berdampak. Empati welas asih mendorong tindakan nyata, dalam batas yang wajar bagi kita.",hint:"Menuntun pada tindakan membantu sesuai kemampuan, atau hanya perasaan / menanggung semua?"},
{n:39,type:"mcq",micro:"Empati untuk kelompok, bukan hanya individu",q:"Empati juga bisa diarahkan pada kelompok yang mengalami kesulitan (mis. korban bencana, kelompok yang diperlakukan tidak adil), yang bisa mendorong...",options:["Kepedulian, solidaritas, & tindakan untuk membantu atau membela mereka","Merasa sedih sebentar lalu melupakannya","Menganggap masalah mereka bukan urusan kita"],answer:0,explain:"Empati yang lebih luas adalah dasar dari kepedulian sosial & keinginan untuk membuat dunia lebih adil bagi semua.",hint:"Mendorong solidaritas & tindakan, atau sedih sebentar / bukan urusan kita?"},
{n:40,type:"open",micro:"Menanggapi berbagai emosi dengan empati",q:"Untuk tiga situasi berikut, tulis satu respons empatik (kalimat yang benar-benar bisa kamu ucapkan) & jelaskan kenapa itu empatik: (1) teman menangis karena hewan peliharaannya mati, (2) teman marah karena merasa diperlakukan tidak adil oleh guru, (3) teman cemas berat sebelum lomba besar.",sample:"(1) Teman menangis karena hewan peliharaannya mati: Respons, 'Aku turut sedih banget. [Nama hewan] pasti sangat berarti buat kamu. Nggak apa-apa nangis, aku di sini.' Kenapa empatik, mengakui besarnya kehilangan (bukan 'ah, cuma binatang'), memvalidasi tangisannya sebagai wajar, & menawarkan kehadiran tanpa menyuruhnya berhenti sedih atau langsung menghibur dengan 'nanti kan bisa punya lagi'. (2) Teman marah karena merasa diperlakukan tidak adil oleh guru: Respons, 'Kedengarannya bikin frustrasi banget ya, ngerasa nggak didengar & diperlakukan beda. Mau cerita lebih detail apa yang terjadi?' Kenapa empatik, memvalidasi perasaan frustrasi & rasa tidak adilnya tanpa langsung membela guru ('mungkin gurunya ada alasannya') atau memanas-manasi ('iya, gurunya emang jahat'); mengajak bercerita lebih supaya ia merasa didengar dulu sebelum membahas apa yang bisa dilakukan. (3) Teman cemas berat sebelum lomba besar: Respons, 'Wajar banget kamu gugup, ini penting buat kamu & kamu udah usaha keras. Kamu lagi pengen ditemenin diem-diem, atau pengen ngobrol buat ngalihin pikiran?' Kenapa empatik, menormalkan kegugupan sebagai wajar (bukan 'santai aja, pasti bisa' yang bisa terasa meremehkan), mengakui usahanya, & menanyakan apa yang ia butuhkan alih-alih berasumsi.",explain:"Jawaban baik: tiga respons yang benar-benar bisa diucapkan (bukan deskripsi umum), masing-masing dengan penjelasan yang menunjukkan pemahaman kenapa itu empatik, memvalidasi perasaan spesifik, tidak meremehkan atau langsung 'memperbaiki', & menghormati kebutuhan orang itu.",hint:"Untuk tiap situasi, hindari: meremehkan ('cuma...'), menggampangkan ('santai aja'), atau langsung solusi. Fokus pada memvalidasi & menanyakan kebutuhan."},

// FASE C — PENERAPAN (41-60): praktik empati
{n:41,type:"mcq",micro:"Mendengarkan aktif untuk emosi",q:"Cara menunjukkan bahwa kamu mendengarkan perasaan seseorang, bukan hanya kata-katanya:",options:["Diam tanpa reaksi apa pun sampai mereka selesai","Sesekali merangkum apa yang mereka rasakan ('jadi kamu ngerasa kecewa sekaligus bingung ya?') & beri ruang bagi mereka mengoreksi","Terus menyela dengan pendapatmu"],answer:1,explain:"Merangkum perasaan (bukan hanya fakta) menunjukkan pemahaman yang lebih dalam & memberi orang kesempatan meluruskan bila kita salah menangkap.",hint:"Merangkum perasaan & beri ruang koreksi, atau menyela / diam total?"},
{n:42,type:"mcq",micro:"Bahasa tubuh empatik",q:"Bahasa tubuh yang menunjukkan empati saat mendengarkan:",options:["Melihat ke HP sambil sesekali 'hmm'","Menyilangkan tangan & melihat ke arah lain","Menghadapkan tubuh ke orang, kontak mata yang wajar, ekspresi yang menanggapi (bukan datar), meletakkan HP"],answer:2,explain:"Perhatian fisik yang terlihat membuat orang merasa benar-benar didengar, bahkan sebelum kita mengucapkan sepatah kata.",hint:"Perhatian fisik yang terlihat, atau lihat HP / menyilangkan tangan?"},
{n:43,type:"mcq",micro:"Menanyakan kebutuhan langsung",q:"Pertanyaan sederhana yang sangat membantu saat seseorang bercerita tentang kesulitan:",options:["'Kamu lagi butuh didengerin aja, butuh saran, atau butuh ditemenin?'","'Kenapa kamu nggak selesaikan aja dari kemarin?'","'Yaudah sih, jangan dipikirin.'"],answer:0,explain:"Orang butuh hal berbeda pada momen berbeda. Menanyakannya langsung mencegah kita memberi hal yang salah (mis. saran saat mereka hanya ingin didengar).",hint:"Menanyakan kebutuhan langsung, atau menyalahkan / meremehkan?"},
{n:44,type:"mcq",micro:"Empati saat tidak tahu harus berkata apa",q:"Kalau seseorang mengalami hal sangat berat & kamu bingung harus berkata apa, respons yang tetap empatik:",options:["Mengubah topik agar tidak canggung","'Aku nggak tau harus bilang apa, tapi aku turut sedih & aku di sini buat kamu.'","Diam & menjauh karena tidak tahu harus bilang apa"],answer:1,explain:"Kejujuran ('aku nggak tau harus bilang apa') yang disertai kehadiran sering lebih berarti daripada mencari kata-kata sempurna atau menghindar.",hint:"Jujur bingung + tetap hadir, atau menjauh / ganti topik?"},
{n:45,type:"tf",micro:"Empati tidak selalu berupa kata-kata",q:"Benar atau Salah: Empati harus selalu berupa kata-kata; tindakan seperti membawakan makanan atau menemani dalam diam tidak dihitung sebagai empati.",answer:false,explain:"Sebaliknya, kadang empati justru paling terasa lewat tindakan sederhana, menemani dalam diam, membantu tugas yang tertunda. Bagi sebagian orang, kehadiran tenang atau bantuan praktis lebih menyampaikan kepedulian daripada kata-kata.",hint:"Bisa lewat tindakan, atau harus selalu berupa kata-kata?"},
{n:46,type:"mcq",micro:"Empati untuk orang yang berbeda pendapat",q:"Saat seseorang menyampaikan pandangan yang sangat berbeda darimu tentang topik yang kamu pedulikan, cara berempati:",options:["Langsung menyerang pandangan mereka sebelum mereka selesai","Setuju saja agar tidak ada konflik","Dengarkan untuk memahami apa pengalaman & nilai di balik pandangan mereka, bukan hanya menunggu untuk membantah"],answer:2,explain:"Memahami 'kenapa mereka berpikir begitu' (pengalaman, nilai, ketakutan) memperkaya pemahaman kita, tanpa berarti kita harus setuju atau menyembunyikan pandangan kita.",hint:"Dengarkan untuk memahami pengalaman & nilai, atau menyerang / setuju demi damai?"},
{n:47,type:"mcq",micro:"Empati dalam kelompok",q:"Dalam kerja kelompok, memperhatikan bila ada anggota yang terlihat kewalahan atau tidak nyaman & menanyakan keadaannya adalah...",options:["Bentuk empati yang membuat kerja sama lebih sehat & anggota merasa didukung","Membuang waktu produktif","Bukan urusan anggota lain"],answer:0,explain:"Kelompok yang anggotanya saling memperhatikan kondisi emosi satu sama lain cenderung bekerja lebih baik & lebih tahan menghadapi tekanan.",hint:"Membuat kerja sama lebih sehat, atau membuang waktu / bukan urusan?"},
{n:48,type:"mcq",micro:"Menghindari empati yang menghakimi",q:"Kalimat yang terlihat 'empatik' tapi sebenarnya menghakimi:",options:["'Aku di sini kalau kamu butuh.'","'Aku ngerti kok kamu sedih, tapi jujur ya, itu salahmu sendiri.'","'Kedengarannya berat banget ya.'"],answer:1,explain:"Menambahkan penghakiman ('tapi itu salahmu') setelah pernyataan empati membatalkan empatinya. Kalau perlu membahas tanggung jawab, lakukan di waktu terpisah setelah orang merasa didengar.",hint:"Yang menambahkan penghakiman, atau yang murni mengakui perasaan?"},
{n:49,type:"mcq",micro:"Empati & memberi ruang",q:"Kalau seseorang tidak siap bercerita, cara empatik menghormati itu:",options:["Terus mendesak sampai mereka bercerita","Tersinggung karena mereka 'tidak percaya' padamu","'Nggak apa-apa kalau belum mau cerita. Aku tetap di sini, kapan pun kamu siap.'"],answer:2,explain:"Empati menghormati batas & kesiapan orang lain. Kehadiran yang sabar tanpa memaksa sendiri sudah merupakan dukungan.",hint:"Hormati kesiapan & tetap ada, atau mendesak / tersinggung?"},
{n:50,type:"order",micro:"Merespons teman yang butuh dukungan",q:"Urutkan langkah merespons teman yang datang dalam keadaan sangat kesulitan.",items:["Berikan perhatian penuh & tunjukkan kamu benar-benar ada untuk mereka","Dengarkan tanpa menghakimi, & validasi perasaannya","Tanyakan apa yang mereka butuhkan saat ini","Setelah mendukung, perhatikan juga kondisimu sendiri & isi kembali energimu bila perlu"],answer:[0,1,2,3],explain:"Hadir penuh → dengarkan & validasi → tanya kebutuhan → rawat diri sendiri setelahnya. Merawat diri di akhir menjaga kita bisa terus mendukung.",hint:"Memperhatikan kondisi diri sendiri dilakukan sebelum atau sesudah mendukung teman?"},
{n:51,type:"mcq",micro:"Empati untuk keluarga",q:"Menerapkan empati di rumah (memahami kenapa orang tua/saudara bersikap tertentu, mereka lelah, khawatir, sedang menghadapi sesuatu) bisa...",options:["Mengurangi konflik keluarga & membuat kita merespons dengan lebih pengertian, bukan langsung tersinggung","Membuat kita selalu mengalah tanpa batas","Tidak relevan untuk hubungan keluarga"],answer:0,explain:"Empati di rumah bukan berarti selalu setuju, tapi memahami 'apa yang mungkin sedang dialami orang ini' sebelum bereaksi.",hint:"Mengurangi konflik & merespons lebih pengertian, atau selalu mengalah / tak relevan?"},
{n:52,type:"tf",micro:"Empati & ketegasan bisa bersamaan",q:"Benar atau Salah: Kita harus memilih antara berempati ATAU menetapkan batas; keduanya tidak bisa disampaikan bersamaan.",answer:false,explain:"Sebaliknya, kita bisa berkata 'Aku paham kamu sedang kesal & butuh bantuan, dan aku tidak bisa membantu dengan cara itu' sekaligus. Empati yang matang justru menyampaikan batas dengan lebih baik karena orang merasa dimengerti.",hint:"Bisa bersamaan, atau harus pilih salah satu?"},
{n:53,type:"mcq",micro:"Empati saat menyampaikan kritik",q:"Sebelum memberi masukan/kritik pada seseorang, membayangkan bagaimana rasanya menerima kata-kata itu membantu kita...",options:["Membuat kritik lebih tajam agar 'nendang'","Memilih kata & cara yang jujur tapi tidak melukai lebih dari perlu, sehingga masukan lebih mungkin diterima","Menjadi tidak jujur & menghindari semua kritik"],answer:1,explain:"Empati membuat kritik lebih efektif, bukan lebih lemah, karena disampaikan dengan cara yang bisa didengar orang tanpa langsung defensif.",hint:"Memilih cara yang jujur tapi tak melukai berlebihan, atau jadi tak jujur / lebih tajam?"},
{n:54,type:"mcq",micro:"Empati untuk yang sulit disukai",q:"Berlatih berempati pada orang yang sulit kamu sukai (bukan berarti membenarkan perilakunya) bisa...",options:["Berarti kamu harus jadi teman dekat mereka","Selalu buang waktu","Membantumu memahami akar perilaku mereka & merespons dengan lebih bijak, & kadang mengurangi rasa benci yang melelahkan"],answer:2,explain:"Memahami 'kenapa orang ini menyebalkan' (mungkin ia tidak aman, kesepian, atau meniru pola yang dilihatnya) tidak membenarkan, tapi bisa membuat kita lebih tenang menghadapinya.",hint:"Membantu memahami & merespons bijak, atau harus jadi teman dekat / buang waktu?"},
{n:55,type:"mcq",micro:"Empati & tidak menyalahkan diri berlebihan",q:"Kalau kamu sudah berusaha berempati & membantu tapi teman tetap kesulitan, sikap yang sehat:",options:["Terima bahwa kamu tidak bisa 'menyelamatkan' semua orang; kamu sudah melakukan bagianmu dengan tulus, & sisanya di luar kendalimu","Menyalahkan diri karena 'gagal membantu'","Menyerah peduli pada orang sepenuhnya"],answer:0,explain:"Empati berarti peduli & membantu sebisamu, bukan bertanggung jawab penuh atas hasil akhir perasaan atau hidup orang lain.",hint:"Terima batas kendalimu, atau menyalahkan diri / menyerah total?"},
{n:56,type:"tf",micro:"Merawat diri agar bisa terus berempati",q:"Benar atau Salah: Menjaga kesejahteraan & mengisi energi sendiri adalah sikap egois yang bertentangan dengan berempati pada orang lain.",answer:false,explain:"Sebaliknya, kita tidak bisa menuang dari cangkir yang kosong. Merawat diri (istirahat, hal menyenangkan, punya dukungan sendiri) justru membuat kita lebih mampu berempati & mendukung orang lain dalam jangka panjang.",hint:"Membuat lebih mampu berempati jangka panjang, atau egois?"},
{n:57,type:"mcq",micro:"Empati lewat pertanyaan yang tepat",q:"Pertanyaan yang menunjukkan empati (bukan interogasi):",options:["'Terus kamu maunya apa?'","'Gimana perasaan kamu sekarang?' 'Apa yang paling berat buat kamu dari situasi ini?' 'Ada yang bisa aku bantu?'","'Kenapa kamu nggak lakukan X dari kemarin?' 'Kamu yakin bukan salahmu?'"],answer:1,explain:"Pertanyaan empatik fokus pada perasaan & kebutuhan mereka, dengan nada yang peduli, bukan menuntut atau menyalahkan.",hint:"Fokus pada perasaan & kebutuhan dengan peduli, atau menuntut / menyalahkan?"},
{n:58,type:"mcq",micro:"Empati untuk orang yang tampak tidak butuh",q:"Orang yang terlihat kuat, ceria, atau populer...",options:["Tidak pernah butuh empati","Selalu baik-baik saja karena terlihat begitu","Tetap bisa sedang menghadapi kesulitan yang tidak terlihat; empati berguna untuk semua orang, bukan hanya yang jelas sedang susah"],answer:2,explain:"Tampilan luar sering tidak menunjukkan seluruh cerita. Menanyakan kabar dengan tulus pada siapa pun (termasuk yang terlihat 'kuat') adalah kebaikan.",hint:"Semua orang bisa butuh empati, atau hanya yang jelas susah?"},
{n:59,type:"mcq",micro:"Empati & konsistensi",q:"Empati paling berdampak bila...",options:["Menjadi kebiasaan yang konsisten dalam cara kita berinteraksi sehari-hari, bukan hanya ditunjukkan sesekali saat ada krisis besar","Hanya ditunjukkan saat ada orang yang mengawasi","Disimpan untuk situasi yang sangat serius saja"],answer:0,explain:"Empati sehari-hari, memperhatikan, mendengarkan, tidak meremehkan, membangun hubungan & lingkungan yang lebih hangat secara terus-menerus.",hint:"Kebiasaan konsisten sehari-hari, atau sesekali saat diawasi / hanya untuk krisis besar?"},
{n:60,type:"open",micro:"Rencana melatih empati",q:"Buat rencana melatih empati selama 2 minggu. Sertakan: (a) satu kebiasaan mendengarkan yang akan kamu terapkan, (b) satu hal yang akan kamu tahan diri dari melakukannya (mis. langsung memberi solusi, membajak cerita orang), (c) satu cara memperluas empati pada pengalaman yang berbeda dari kamu, (d) bagaimana kamu akan menjaga batas & merawat diri agar tidak kelelahan empati, (e) cara kamu akan tahu apakah latihan ini membuat perbedaan.",sample:"(a) Kebiasaan mendengarkan: setiap kali seseorang bercerita tentang perasaan, aku akan meletakkan HP, menghadapkan tubuhku ke mereka, & sebelum menanggapi, merangkum dulu apa yang kutangkap ('jadi kamu ngerasa ___ ya?') untuk memastikan aku benar-benar paham. (b) Yang akan kutahan: aku akan menahan diri dari langsung memberi solusi atau berkata 'aku juga pernah begitu' di awal; aku akan menunggu sampai mereka selesai bercerita & menanyakan dulu apa yang mereka butuhkan. (c) Memperluas empati pada yang berbeda: aku akan membaca atau menonton minimal 2 cerita/wawancara tentang kehidupan orang yang latar belakang atau pengalamannya jauh berbeda dari aku (misalnya penyandang disabilitas, atau orang dari daerah/negara lain), & merefleksikan apa yang baru kupahami tentang perasaan & tantangan mereka. (d) Menjaga batas & merawat diri: aku akan sadar bahwa mendengarkan masalah berat butuh energi, jadi setelah menemani teman yang sedang berat, aku akan melakukan sesuatu yang mengisi energiku (jalan, musik, waktu sendiri sebentar), & bila aku sendiri sedang berat, aku akan jujur mengatakan 'aku pengen bantu tapi aku juga lagi kurang baik hari ini, bisa nanti ya?' daripada memaksakan diri sampai kewalahan. (e) Mengetahui perbedaannya: di akhir 2 minggu, aku akan bertanya pada diriku, apakah ada teman yang bilang aku 'lebih enak diajak cerita' belakangan ini? apakah aku sendiri merasa lebih jarang buru-buru menghakimi orang? apakah aku bisa menyebut minimal 2 hal baru yang kupahami tentang pengalaman orang yang berbeda? Kalau ya, latihan ini membuat perbedaan.",explain:"Jawaban baik: kebiasaan mendengarkan yang konkret (merangkum perasaan), satu hal spesifik yang ditahan (solusi cepat / membajak cerita), cara nyata memperluas empati lintas perbedaan (kisah orang berbeda), rencana konkret menjaga batas & merawat diri (tidak melebih-lebihkan diri sendiri sebagai 'penyelamat'), & cara mengevaluasi yang bisa diperiksa (umpan balik teman, refleksi kebiasaan menghakimi, pemahaman baru).",hint:"Bagian (d) penting untuk topik ini, empati tanpa batas menyebabkan kelelahan; buat rencana konkret merawat diri & jujur soal kapasitas."},

// FASE D — PENALARAN (61-80): batas, empati & keadilan, kompleksitas
{n:61,type:"mcq",micro:"Kelelahan empati",q:"'Kelelahan empati' (compassion fatigue) adalah keadaan ketika...",options:["Empati membuat orang jadi lebih kuat tanpa efek samping","Seseorang yang sering menyerap emosi berat orang lain menjadi lelah secara emosional & sulit terus peduli seperti biasa","Seseorang menjadi terlalu peduli sehingga bahagia terus"],answer:1,explain:"Mengenali tanda kelelahan empati (mudah tersinggung, ingin menghindari orang, terasa 'kosong') penting agar kita bisa merawat diri sebelum benar-benar kewalahan.",hint:"Lelah secara emosional & sulit terus peduli, atau bahagia terus / tanpa efek?"},
{n:62,type:"mcq",micro:"Empati bukan kewajiban tanpa batas",q:"Kita TIDAK berkewajiban...",options:["Bersikap baik & mencoba memahami orang","Membantu ketika kita mampu","Menanggung sepenuhnya semua perasaan semua orang, membiarkan diri diperlakukan buruk atas nama 'pengertian', atau mengorbankan seluruh kebutuhan kita untuk orang lain"],answer:2,explain:"Empati yang sehat punya batas. Peduli pada orang lain & merawat diri sendiri keduanya penting & tidak bertentangan.",hint:"Tidak wajib menanggung semua / dibiarkan diperlakukan buruk, atau tidak wajib bersikap baik sama sekali?"},
{n:63,type:"mcq",micro:"Empati & manipulasi",q:"Kadang seseorang bisa menyalahgunakan empati orang lain (mis. terus-menerus memainkan rasa iba untuk mendapat sesuatu). Kalau kamu merasa ini terjadi...",options:["Kamu boleh menetapkan batas dengan tetap sopan; empati tidak berarti membiarkan diri dimanfaatkan berulang kali","Kamu harus terus memberi apa pun yang diminta karena 'itu empati'","Kamu jadi orang jahat kalau menolak"],answer:0,explain:"Membedakan 'orang yang benar-benar butuh & kesulitan' dari 'pola yang memanfaatkan kebaikan' adalah bagian dari empati yang bijak, bukan kurang peduli.",hint:"Boleh menetapkan batas, atau harus terus memberi / jadi jahat?"},
{n:64,type:"tf",micro:"Empati mendukung keadilan",q:"Benar atau Salah: Empati pada mereka yang diperlakukan tidak adil dapat mendorong kita untuk membela mereka & bertindak untuk membuat situasi lebih adil, empati & keadilan sering berjalan bersama.",answer:true,explain:"Merasakan ketidakadilan yang dialami orang lain sering menjadi motivasi untuk bertindak, bukan hanya bersimpati diam-diam.",hint:"Mendorong membela & bertindak adil, atau hanya bersimpati diam?"},
{n:65,type:"mcq",micro:"Empati yang bias",q:"Kita cenderung lebih mudah berempati pada orang yang mirip dengan kita (latar belakang, minat, pengalaman). Menyadari kecenderungan ini membantu kita...",options:["Merasa tidak apa-apa hanya peduli pada yang mirip kita","Sengaja berusaha lebih memahami orang yang berbeda dari kita, agar empati kita lebih adil & tidak hanya untuk 'kelompok kita'","Menyerah berempati pada siapa pun karena 'pasti bias'"],answer:1,explain:"Empati yang matang berusaha melampaui 'lingkaran kenyamanan' untuk juga memahami mereka yang berbeda, karena semua orang layak dipahami.",hint:"Sengaja berusaha memahami yang berbeda, atau menyerah / cukup peduli pada yang mirip?"},
{n:66,type:"mcq",micro:"Empati saat kita korban",q:"Kalau kamu diperlakukan tidak adil oleh seseorang, apakah kamu 'harus' berempati pada mereka?",options:["Ya, kamu selalu wajib berempati bahkan pada yang menyakitimu","Tidak, empati pada orang yang menyakitimu selalu salah","Kamu boleh, bila itu membantumu memahami & merespons dengan bijak, tapi kamu tidak wajib, terutama tidak wajib mengorbankan hakmu atau membiarkan perlakuan buruk berlanjut"],answer:2,explain:"Empati adalah pilihan yang bisa membantu, bukan kewajiban yang memaksa kita mengabaikan keadilan atau keselamatan diri sendiri.",hint:"Boleh tapi tidak wajib mengorbankan hak/keselamatan, atau selalu wajib / selalu salah?"},
{n:67,type:"mcq",micro:"Empati & perbedaan pendapat yang tajam",q:"Berempati pada seseorang yang pandangannya kamu anggap merugikan (mis. pandangan yang tidak adil pada kelompok tertentu) berarti...",options:["Berusaha memahami pengalaman & ketakutan di balik pandangan itu (yang bisa membantu dialog), tanpa berarti membenarkan atau menerima pandangan yang merugikan itu","Harus menerima & menyetujui pandangan itu","Tidak boleh mencoba memahaminya sama sekali"],answer:0,explain:"Empati membantu kita memahami akar sebuah pandangan (yang bisa berguna untuk mengubah pikiran orang lewat dialog), tanpa mengharuskan kita setuju dengan isi pandangan yang merugikan.",hint:"Memahami akar tanpa membenarkan isi yang merugikan, atau harus menerima / tak boleh memahami?"},
{n:68,type:"tf",micro:"Empati sebagai keterampilan seumur hidup",q:"Benar atau Salah: Kemampuan berempati terus berkembang sepanjang hidup seiring kita bertemu lebih banyak orang & pengalaman yang berbeda dari kita.",answer:true,explain:"Setiap orang baru yang kita coba pahami memperluas 'kapasitas empati' kita. Ini bukan keterampilan yang 'selesai' dipelajari.",hint:"Terus berkembang seumur hidup, atau selesai di usia tertentu?"},
{n:69,type:"mcq",micro:"Empati vs 'aku tahu persis perasaanmu'",q:"Mengatakan 'aku tahu PERSIS perasaanmu' pada seseorang yang mengalami sesuatu yang berat bisa...",options:["Tidak berpengaruh pada bagaimana mereka merasa","Terasa meremehkan bagi sebagian orang, karena pengalaman tiap orang unik; lebih aman 'aku nggak bisa sepenuhnya tahu rasanya, tapi kedengarannya sangat berat'","Selalu membantu karena menunjukkan kita mengerti"],answer:1,explain:"Menghormati bahwa pengalaman mereka unik ('aku tidak sepenuhnya tahu, tapi aku ingin memahami') sering lebih empatik daripada mengklaim tahu persis.",hint:"Bisa terasa meremehkan, atau selalu membantu / tak berpengaruh?"},
{n:70,type:"tf",micro:"Empati membangun komunitas yang lebih baik",q:"Benar atau Salah: Komunitas (kelas, keluarga, lingkungan) di mana orang saling berusaha memahami perasaan satu sama lain cenderung lebih hangat, lebih cepat membantu yang kesulitan, & lebih tahan menghadapi masalah bersama.",answer:true,explain:"Empati kolektif adalah fondasi dari kelompok yang peduli & saling mendukung.",hint:"Membangun komunitas lebih hangat & tahan, atau tak berpengaruh?"},
{n:71,type:"mcq",micro:"Empati & perbedaan cara mengekspresikan",q:"Kalau seseorang tidak mengekspresikan perasaannya dengan cara yang kamu harapkan (mis. tidak menangis saat sedih, atau justru tertawa saat gugup), sikap empatik:",options:["Menganggap mereka 'tidak benar-benar sedih' karena tidak menangis","Menyuruh mereka mengekspresikan 'dengan benar'","Menerima bahwa orang mengekspresikan emosi dengan cara berbeda; caranya menunjukkan tidak selalu mencerminkan seberapa dalam ia merasakan"],answer:2,explain:"Ekspresi emosi dipengaruhi kepribadian, budaya, & kebiasaan. Empati menghormati keberagaman ini, bukan menuntut ekspresi tertentu.",hint:"Menerima keberagaman ekspresi, atau menuntut cara tertentu?"},
{n:72,type:"mcq",micro:"Empati & menahan penilaian moral",q:"Berempati pada seseorang yang membuat pilihan yang tidak kamu setujui (mis. seorang teman yang menyontek) berarti...",options:["Berusaha memahami tekanan & ketakutan yang mungkin mendorong pilihan itu, sambil tetap bisa berpendapat bahwa pilihannya salah & mendorong yang lebih baik","Harus menyetujui pilihan mereka","Tidak boleh membahas pilihan itu sama sekali"],answer:0,explain:"Memahami 'kenapa' seseorang membuat pilihan buruk membantu kita membantunya lebih baik, tanpa berarti kita menyetujui pilihan itu.",hint:"Memahami tekanan tanpa menyetujui pilihan, atau harus setuju / tak boleh membahas?"},
{n:73,type:"mcq",micro:"Empati untuk diri sendiri di masa lalu",q:"Merasa malu atau menyesal atas hal yang kamu lakukan di masa lalu (saat kamu lebih muda/kurang tahu) bisa disikapi dengan empati pada diri sendiri, yaitu...",options:["Berpura-pura hal itu tidak pernah terjadi","'Aku waktu itu belum tahu & belum sedewasa sekarang; aku sudah belajar & bertumbuh sejak itu', sambil tetap mengakui & memperbaiki bila perlu","Terus menghukum diri sendiri tanpa henti"],answer:1,explain:"Belas kasih pada diri sendiri mengakui bahwa kita berubah & belajar. Ini berbeda dari menghindari tanggung jawab, keduanya bisa berjalan bersama.",hint:"Pengertian pada diri yang dulu + belajar & perbaiki, atau hukum diri terus / menyangkal?"},
{n:74,type:"mcq",micro:"Empati & tidak menanggung tanggung jawab orang lain",q:"Empati pada teman yang sedang kesulitan TIDAK berarti...",options:["Kamu tidak boleh membantu sama sekali","Kamu harus menjauh agar tidak terlibat","Kamu bertanggung jawab menyelesaikan semua masalahnya atau membuat semua keputusan untuknya; kamu bisa mendukung sambil menghormati bahwa hidupnya adalah tanggung jawabnya sendiri"],answer:2,explain:"Empati yang sehat mendukung orang menemukan kekuatan & jalan mereka sendiri, bukan mengambil alih hidup mereka.",hint:"Mendukung tanpa mengambil alih tanggung jawab hidup mereka, atau tak boleh bantu / harus menjauh?"},
{n:75,type:"order",micro:"Menyeimbangkan empati & batas diri",q:"Urutkan langkah menghadapi situasi di mana seseorang terus meminta dukungan emosi dari kamu sampai kamu kelelahan.",items:["Sadari bahwa kamu merasa kewalahan & itu sinyal untuk memperhatikan batasmu","Akui perasaan & kebutuhan orang itu ('aku tahu kamu lagi berat & butuh cerita')","Sampaikan batasmu dengan jujur & baik ('aku juga butuh waktu untuk diriku, aku nggak bisa selalu jadi tempat cerita utama')","Bantu mereka menemukan dukungan lain juga (orang lain, atau orang dewasa/profesional bila situasinya berat)"],answer:[0,1,2,3],explain:"Sadari batasmu → akui kebutuhan mereka → sampaikan batasmu dengan baik → bantu cari dukungan lain. Menetapkan batas dengan empati, bukan dengan menolak dingin.",hint:"Menyampaikan batasmu dilakukan sebelum atau sesudah mengakui kebutuhan orang itu?"},
{n:76,type:"tf",micro:"Empati tidak sama dengan lemah",q:"Benar atau Salah: Orang yang berempati sering justru lebih kuat & lebih efektif dalam memimpin, menyelesaikan konflik, & bekerja sama, karena mereka memahami orang & bisa menggerakkan kerja sama yang tulus.",answer:true,explain:"Empati adalah kekuatan, bukan kelemahan. Pemimpin & rekan yang empatik sering lebih dipercaya & lebih mampu menyatukan orang.",hint:"Kekuatan yang efektif, atau kelemahan?"},
{n:77,type:"mcq",micro:"Empati & mendengar tanpa memperbaiki",q:"Salah satu hal tersulit tapi paling empatik: bisa duduk bersama seseorang dalam kesulitan mereka TANPA...",options:["Buru-buru mencoba memperbaiki, menghibur berlebihan, atau membuatnya 'lebih positif'; kadang orang butuh perasaannya diakui, bukan diubah","Pernah mengatakan apa pun sama sekali","Menunjukkan bahwa kamu peduli"],answer:0,explain:"Dorongan untuk 'memperbaiki' perasaan orang sering datang dari ketidaknyamanan kita sendiri. Menahannya & sekadar hadir adalah bentuk empati yang dalam.",hint:"Tanpa buru-buru memperbaiki / memaksa positif, atau tanpa berkata apa pun / tanpa menunjukkan peduli?"},
{n:78,type:"mcq",micro:"Empati & pertumbuhan pribadi",q:"Berlatih empati juga membantu pertumbuhan diri kita sendiri karena...",options:["Tidak ada manfaatnya bagi diri sendiri, hanya untuk orang lain","Memahami banyak sudut pandang & perasaan membuat kita lebih bijak, lebih sabar, & lebih mampu menghadapi keberagaman hidup","Membuat kita kehilangan pendirian sendiri"],answer:1,explain:"Empati memperkaya pemahaman kita tentang manusia secara umum, yang berguna dalam hampir setiap aspek kehidupan.",hint:"Membuat lebih bijak & sabar, atau kehilangan pendirian / tak bermanfaat bagi diri?"},
{n:79,type:"mcq",micro:"Empati sebagai kebiasaan, bukan performa",q:"Empati yang tulus berbeda dari 'pura-pura empati' (untuk terlihat baik) karena...",options:["Keduanya sama saja hasilnya","Pura-pura empati selalu lebih efektif","Empati tulus benar-benar berusaha memahami & peduli, konsisten meski tidak ada yang melihat; pura-pura empati berhenti saat tidak ada penonton"],answer:2,explain:"Orang biasanya bisa merasakan perbedaan antara perhatian yang tulus & yang dibuat-buat. Empati yang konsisten membangun kepercayaan sejati.",hint:"Tulus & konsisten meski tak dilihat, atau pura-pura yang berhenti tanpa penonton?"},
{n:80,type:"open",micro:"Empati dengan batas yang sehat",q:"Bayangkan seorang teman yang setiap hari, kadang berkali-kali sehari, datang padamu untuk menceritakan masalah beratnya, mengharapkan kamu selalu tersedia & merasa kecewa bila kamu tidak segera membalas atau tidak bisa menemani. Kamu peduli padanya tapi mulai merasa sangat lelah & tidak punya waktu untuk dirimu sendiri. Analisis: (a) kenapa empati saja tidak cukup di sini & batas diperlukan, (b) bagaimana kamu bisa menetapkan batas dengan tetap menunjukkan kepedulian, (c) bagaimana kamu bisa membantunya menemukan dukungan yang lebih memadai, (d) kapan situasi ini menunjukkan bahwa temanmu mungkin butuh bantuan orang dewasa/profesional.",sample:"(a) Kenapa batas diperlukan: empati berarti aku peduli & ingin membantu, tapi aku bukan satu-satunya sumber dukungan yang seharusnya ia miliki, & aku juga manusia dengan batas energi, waktu, & kebutuhan sendiri. Kalau aku terus memaksakan diri selalu tersedia, aku akan mengalami kelelahan empati, jadi mudah tersinggung, kehilangan waktu untuk hal-hal pentingku, & akhirnya justru tidak bisa mendukungnya dengan tulus; ini tidak baik untuk kami berdua. (b) Menetapkan batas dengan peduli: aku akan bilang sesuatu seperti, 'Aku sayang sama kamu & aku peduli sama apa yang kamu alami. Tapi jujur, aku merasa kewalahan kalau harus selalu langsung ada setiap saat, & aku juga butuh waktu untuk diriku. Aku tetap mau jadi tempat cerita kamu, cuma mungkin nggak bisa setiap kali & setiap saat, boleh ya?' Aku menyampaikannya dengan lembut tapi jelas, & tidak minta maaf berlebihan seolah punya batas itu salah. (c) Membantunya cari dukungan lain: aku akan mendorongnya untuk juga bercerita ke orang lain yang ia percaya (keluarga, teman lain), & menyarankan bahwa kalau masalahnya terasa terlalu berat, bicara dengan konselor sekolah bisa sangat membantu, bukan karena aku menolaknya, tapi karena beberapa hal butuh dukungan yang lebih dari yang bisa diberikan teman sebaya. (d) Kapan butuh bantuan dewasa/profesional: kalau intensitas & frekuensi kebutuhannya tidak berkurang meski sudah lama, kalau ia menyebutkan perasaan yang sangat gelap atau putus asa, kalau masalahnya jelas di luar kapasitas kami berdua untuk menyelesaikannya, atau kalau aku merasa sangat khawatir tentang keadaannya, maka aku akan mendorongnya bicara ke orang dewasa tepercaya, & bila ia menolak sementara aku sangat khawatir, aku sendiri akan bicara ke orang dewasa tepercaya karena keselamatan & kesejahteraannya lebih penting daripada menjaga rahasia.",explain:"Jawaban baik: penjelasan yang jelas kenapa empati tanpa batas merugikan kedua pihak (kelelahan empati membuat dukungan jadi tidak tulus), cara menetapkan batas yang tetap hangat & tidak minta maaf berlebihan, cara membantu teman menemukan dukungan lain (bukan sekadar 'menolak'), & kriteria konkret kapan melibatkan orang dewasa termasuk kesediaan bertindak sendiri bila sangat khawatir.",hint:"Kuncinya: menetapkan batas BUKAN berarti berhenti peduli; sampaikan dengan hangat, & bantu teman menemukan dukungan yang lebih memadai daripada bergantung penuh pada satu teman sebaya."},

// FASE E — TANTANGAN (81-100): skenario & kapstone
{n:81,type:"mcq",micro:"Skenario: teman baru yang terlihat kesepian",q:"Ada siswa pindahan yang selalu sendirian saat istirahat & terlihat murung. Cara menunjukkan empati:",options:["Ajak dia bicara atau bergabung dengan tulus ('hai, mau makan bareng kami?'), tanpa memaksa bila ia belum siap, & lakukan lagi lain hari","Membicarakannya dengan teman lain sambil merasa kasihan dari jauh","Menganggap 'nanti juga dia dapat teman sendiri'"],answer:0,explain:"Empati yang berbuah tindakan, sekadar mengajak bergabung, bisa sangat berarti bagi seseorang yang merasa terasing. Kesabaran & konsistensi penting bila ia belum langsung terbuka.",hint:"Ajak dengan tulus & konsisten, atau kasihan dari jauh / abai?"},
{n:82,type:"mcq",micro:"Skenario: teman bercerita, kamu ingin memberi solusi",q:"Temanmu bercerita panjang tentang kekesalannya pada situasi rumah. Kamu punya banyak ide solusi. Langkah yang lebih empatik:",options:["Dengarkan sambil memikirkan solusi & langsung menyampaikannya begitu ia jeda","Dengarkan sampai selesai, validasi perasaannya, lalu tanya 'kamu pengen dengerin pendapatku, atau lagi butuh didengerin aja?'","Potong ceritanya untuk langsung memberi semua solusimu"],answer:1,explain:"Solusi bisa berharga, tapi hanya setelah orang merasa didengar & bila mereka memang menginginkannya. Menanyakan dulu menghindari respons yang salah.",hint:"Dengarkan penuh + validasi + tanya kebutuhan, atau potong / langsung solusi?"},
{n:83,type:"mcq",micro:"Skenario: dua teman berkonflik, kamu di tengah",q:"Dua sahabatmu bertengkar & masing-masing menceritakan versinya padamu, berharap kamu setuju dengan mereka. Sikap empatik & adil:",options:["Langsung berpihak pada yang cerita duluan","Menghindari keduanya agar tidak terlibat","Dengarkan keduanya dengan empati, validasi perasaan masing-masing tanpa menghakimi salah satu, & bantu mereka saling memahami, tanpa harus 'memihak'"],answer:2,explain:"Sebagai pihak ketiga, empati untuk keduanya bisa membantu mereka melihat sisi satu sama lain, lebih dari sekadar menjadi 'hakim'.",hint:"Empati untuk keduanya & bantu saling memahami, atau memihak / menghindar?"},
{n:84,type:"mcq",micro:"Skenario: kamu tidak setuju tapi ingin memahami",q:"Seseorang menyampaikan pandangan yang sangat berbeda darimu tentang topik penting. Cara menunjukkan empati tanpa mengkhianati keyakinanmu:",options:["'Aku lihat kamu ngerasa kuat soal ini. Boleh cerita apa yang bikin kamu berpikir begitu? Aku pengen ngerti, meskipun mungkin aku nggak sependapat.'","Langsung membantah sebelum ia selesai bicara","Berpura-pura setuju agar percakapan cepat selesai"],answer:0,explain:"Menunjukkan rasa ingin tahu yang tulus tentang alasan seseorang, sambil jujur bahwa kamu mungkin tidak sependapat, adalah empati yang jujur.",hint:"Rasa ingin tahu tulus + jujur soal beda pendapat, atau membantah / pura-pura setuju?"},
{n:85,type:"tf",micro:"Empati adalah keterampilan hidup penting",q:"Benar atau Salah: Kemampuan berempati berperan besar dalam kualitas hubungan, kerja sama, kepemimpinan, penyelesaian konflik, & menjadi bagian dari komunitas yang saling peduli.",answer:true,explain:"Empati adalah salah satu keterampilan sosial-emosi paling penting untuk kehidupan yang bermakna & hubungan yang sehat.",hint:"Berperan besar & luas, atau hanya soal 'baik hati'?"},
{n:86,type:"mcq",micro:"Skenario: kamu lelah tapi teman butuh",q:"Kamu sangat lelah setelah hari yang berat, & temanmu menelepon dalam keadaan menangis butuh cerita. Respons yang jujur & empatik:",options:["Menolak menjawab telepon tanpa penjelasan apa pun","Dengarkan sebisamu sambil jujur ('aku dengerin ya, tapi maaf kalau aku agak kurang responsif, aku lagi capek banget'), atau bila benar-benar tidak sanggup, 'aku peduli & pengen dengerin, tapi aku bener-bener nggak sanggup malam ini, bisa besok pagi? atau ada orang lain yang bisa kamu hubungi sekarang?'","Selalu memaksakan diri mendengarkan penuh meski kewalahan"],answer:1,explain:"Empati tidak menuntut kita mengabaikan kondisi sendiri. Kejujuran yang lembut & membantu teman menemukan alternatif adalah pilihan yang sehat.",hint:"Dengarkan sebisamu / jujur soal kapasitas & bantu cari alternatif, atau paksakan penuh / abaikan tanpa kabar?"},
{n:87,type:"mcq",micro:"Skenario: teman mengekspresikan sedih dengan marah",q:"Temanmu, alih-alih terlihat sedih, jadi mudah marah & ketus belakangan ini. Kamu curiga ada yang berat sedang ia alami. Cara empatik menanggapinya:",options:["Membalas ketusnya dengan ketus juga","Menjauhinya karena 'sikapnya nggak enak'","Tetap sabar (tidak membalas ketusnya), & di momen yang tenang tanyakan dengan lembut 'kamu kelihatan lagi berat belakangan ini, ada yang mau kamu ceritain? aku di sini'"],answer:2,explain:"Marah yang tidak biasa sering menutupi kesedihan atau tekanan. Empati melihat 'apa yang mungkin ada di balik ini' & menawarkan ruang aman, tanpa membiarkan diri diperlakukan buruk terus-menerus.",hint:"Sabar & tawarkan ruang di momen tenang, atau balas ketus / menjauh?"},
{n:88,type:"mcq",micro:"Skenario: empati untuk orang dewasa di rumah",q:"Orang tuamu belakangan lebih mudah marah & tegang. Menerapkan empati berarti...",options:["Mencoba memahami bahwa mereka mungkin sedang menghadapi tekanan (pekerjaan, keuangan, hal lain) & merespons dengan lebih pengertian, sambil tetap bisa menyampaikan perasaanmu dengan baik","Selalu mengalah pada semua & memendam perasaanmu","Menganggap sikap mereka sepenuhnya bukan masalahmu"],answer:0,explain:"Empati di rumah bukan berarti kehilangan suara sendiri, tapi memahami konteks orang lain sebelum bereaksi, & tetap bisa berkomunikasi jujur dengan cara yang menghormati.",hint:"Pahami konteks mereka + tetap bisa menyampaikan perasaan, atau selalu mengalah / abai?"},
{n:89,type:"mcq",micro:"Skenario: teman terus meminta bantuan tugas",q:"Temanmu selalu meminta kamu mengerjakan bagiannya di tugas kelompok dengan alasan ia 'nggak bisa'. Kamu ingin membantu tapi ini tidak adil & melelahkan. Empati dengan batas:",options:["Menolak membantu sama sekali & memarahinya","'Aku ngerti kamu ngerasa kesulitan & aku mau bantu kamu belajar caranya, tapi aku nggak bisa terus ngerjain bagian kamu, itu nggak adil buat aku & kamu jadi nggak belajar. Ayo kita kerjain bareng.'","Terus mengerjakan bagiannya karena 'kasihan'"],answer:1,explain:"Empati mengakui kesulitannya & menawarkan bantuan yang tepat (mengajari, mengerjakan bersama), sambil dengan jelas menolak pola yang tidak adil.",hint:"Akui kesulitan + tawarkan bantuan yang tepat + tolak pola tak adil, atau terus mengerjakan / menolak & memarahi?"},
{n:90,type:"order",micro:"Proyek: sebulan meningkatkan empati",q:"Urutkan langkah proyek 'jadi pendengar & teman yang lebih empatik dalam sebulan'.",items:["Minggu 1: fokus melatih mendengarkan penuh, meletakkan HP & merangkum perasaan orang sebelum menanggapi","Minggu 2: fokus menahan diri dari langsung memberi solusi, tanyakan dulu 'butuh didengar atau butuh saran?'","Minggu 3: fokus memperluas empati pada orang yang berbeda dari kamu (dengar cerita/pengalaman mereka)","Minggu 4: fokus menjaga batas & merawat diri agar bisa terus berempati tanpa kelelahan; refleksikan pertumbuhanmu"],answer:[0,1,2,3],explain:"Mendengarkan penuh → menahan solusi → memperluas pada yang berbeda → menjaga batas & refleksi. Membangun keterampilan bertahap, diakhiri dengan menjaga keberlanjutan.",hint:"Fokus menjaga batas & merawat diri ditempatkan di awal atau akhir proyek?"},
{n:91,type:"mcq",micro:"Skenario: kamu menyadari empatimu bias",q:"Kamu menyadari kamu lebih mudah berempati pada teman yang mirip denganmu & cenderung meremehkan perasaan siswa dari kelompok lain. Langkah pertumbuhan:",options:["Anggap wajar & terus hanya peduli pada yang mirip","Merasa terlalu bersalah sampai menghindari semua interaksi","Akui kecenderungan itu, & sengaja berlatih mendengarkan & memahami pengalaman siswa yang berbeda darimu dengan sungguh-sungguh"],answer:2,explain:"Menyadari bias empati kita sendiri adalah langkah pertama memperbaikinya. Empati yang adil berusaha melampaui 'lingkaran kenyamanan'.",hint:"Akui & sengaja berlatih memahami yang berbeda, atau anggap wajar / rasa bersalah lumpuh?"},
{n:92,type:"tf",micro:"Empati membutuhkan latihan & niat",q:"Benar atau Salah: Empati yang dalam bukan hanya perasaan spontan, tapi juga pilihan & latihan, sengaja memperhatikan, mendengarkan, menahan penghakiman, & berusaha memahami, terutama pada orang yang berbeda dari kita.",answer:true,explain:"Empati punya komponen otomatis (ikut merasakan) & komponen yang dilatih (sengaja berusaha memahami). Keduanya bisa dikembangkan.",hint:"Butuh pilihan & latihan juga, atau murni spontan?"},
{n:93,type:"mcq",micro:"Skenario: teman menolak dukunganmu",q:"Kamu menawarkan dukungan pada teman yang sedang kesulitan, tapi ia menolak & bilang 'aku bisa sendiri kok'. Sikap empatik:",options:["Hormati pilihannya, tapi biarkan ia tahu tawaranmu tetap ada ('oke, tapi kalau berubah pikiran, aku di sini ya'), tanpa memaksa atau tersinggung","Memaksanya menerima bantuanmu","Tersinggung & tidak pernah menawarkan bantuan lagi"],answer:0,explain:"Empati menghormati otonomi orang lain. Kadang orang butuh tahu bahwa dukungan tersedia tanpa merasa dipaksa menerimanya.",hint:"Hormati pilihannya & biarkan tawaran tetap ada, atau memaksa / tersinggung?"},
{n:94,type:"mcq",micro:"Skenario: empati saat orang membuat kesalahan yang merugikanmu",q:"Seseorang lupa janji penting & merugikanmu, lalu meminta maaf dengan tulus & menjelaskan bahwa ia sedang menghadapi banyak hal berat. Sikap yang menyeimbangkan empati & kejujuran:",options:["Menolak permintaan maafnya & memutus hubungan","Terima permintaan maafnya bila kamu siap, akui bahwa kamu memahami ia sedang berat, tapi juga jujur bahwa kejadian itu merugikanmu & kamu berharap ke depan bisa lebih dapat diandalkan","Langsung memaafkan sepenuhnya & berpura-pura tidak terganggu sama sekali"],answer:1,explain:"Empati (memahami kesulitannya) & kejujuran (mengakui bahwa itu merugikanmu) bisa berjalan bersama. Kamu tidak harus menyembunyikan dampaknya pada dirimu demi 'pengertian'.",hint:"Terima maaf + akui kesulitannya + jujur soal dampak padamu, atau maaf pura-pura tak terganggu / putus hubungan?"},
{n:95,type:"tf",micro:"Empati menjadikan kita bagian solusi",q:"Benar atau Salah: Semakin banyak orang yang mempraktikkan empati dalam interaksi sehari-hari, semakin hangat & saling mendukung lingkungan menjadi bagi semua orang.",answer:true,explain:"Empati individu menumpuk menjadi budaya kolektif. Kebiasaan memahami & peduli yang menyebar luas mengubah kualitas sebuah komunitas.",hint:"Menjadikan lingkungan lebih hangat bersama, atau tak berpengaruh secara kolektif?"},
{n:96,type:"mcq",micro:"Skenario: menjadi teladan empati",q:"Adik/sepupu yang lebih muda mengamati bagaimana kamu memperlakukan orang lain. Cara menjadi teladan empati:",options:["Bersikap empatik hanya saat ada orang yang menilai","Menganggap perilakumu tidak memengaruhi mereka","Konsisten menunjukkan mendengarkan dengan sungguh-sungguh, tidak meremehkan perasaan orang, & memperlakukan orang yang berbeda dengan hormat, meski tidak ada yang mengawasi"],answer:2,explain:"Anak belajar berempati terutama dari melihat orang di sekitar mereka melakukannya secara tulus & konsisten.",hint:"Konsisten & tulus meski tak diawasi, atau hanya saat dinilai / anggap tak berpengaruh?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup terampil berempati:",options:["Kamu bisa mendengarkan tanpa buru-buru menghakimi atau memperbaiki, memvalidasi perasaan orang, menanyakan kebutuhan mereka, memperluas empati pada yang berbeda, & menjaga batas diri yang sehat","Kamu hafal definisi empati tapi tetap meremehkan perasaan orang","Kamu menanggung semua perasaan semua orang sampai kewalahan terus-menerus"],answer:0,explain:"Keterampilan sejati: mendengarkan tanpa menghakimi + memvalidasi + menanyakan kebutuhan + memperluas + menjaga batas. Bukan hafalan atau tanpa batas.",hint:"Mendengarkan + validasi + tanya kebutuhan + memperluas + jaga batas, atau hafal tanpa praktik / tanpa batas?"},
{n:98,type:"mcq",micro:"Empati & keadilan sosial",q:"Empati yang meluas pada kelompok yang mengalami ketidakadilan bisa mendorong seseorang untuk...",options:["Menganggap ketidakadilan yang dialami orang lain bukan urusannya","Belajar lebih dalam tentang situasi mereka, menyuarakan dukungan, & berkontribusi pada perubahan yang lebih adil","Merasa sedih sebentar lalu tidak melakukan apa pun"],answer:1,explain:"Empati yang lengkap sering menjadi motivasi untuk peduli & bertindak, bukan hanya merasakan lalu melupakan.",hint:"Mendorong belajar & bertindak untuk keadilan, atau sedih sebentar / bukan urusan?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'empati & memahami orang lain':",options:["Selalu setuju dengan semua orang & menanggung semua perasaan mereka","Merasa kasihan dari jauh tanpa benar-benar memahami","Perhatikan & dengarkan sungguh-sungguh untuk memahami perasaan & kebutuhan orang, validasi tanpa menghakimi, tanggapi sesuai kebutuhan mereka, perluas pemahamanmu pada orang yang berbeda, & jaga batas diri agar bisa terus peduli"],answer:2,explain:"Perhatikan + dengarkan + validasi + tanggapi sesuai kebutuhan + perluas + jaga batas. Empati yang sehat memahami & peduli, tanpa kehilangan diri sendiri.",hint:"Dengarkan + validasi + tanggapi + perluas + jaga batas, atau selalu setuju & tanggung semua / kasihan dari jauh?"},
{n:100,type:"open",micro:"Kapstone: hidup dengan empati",q:"Tulis rencana pribadi untuk hidup dengan lebih banyak empati. Sertakan: (a) 3-4 kebiasaan empati yang akan kamu praktikkan sehari-hari, (b) satu hal yang akan kamu tahan diri dari melakukannya saat orang bercerita, (c) bagaimana kamu akan sengaja memperluas empati pada orang yang berbeda dari kamu, (d) bagaimana kamu akan menjaga batas & merawat diri agar tidak kelelahan empati, (e) bagaimana kamu akan menyeimbangkan empati dengan tetap jujur & tegas saat diperlukan, (f) bagaimana kamu akan tahu bahwa empati membuat perbedaan dalam hidupmu & hubunganmu.",sample:"(a) Kebiasaan empati sehari-hari: (1) Saat seseorang bercerita tentang perasaan, aku meletakkan HP & benar-benar mendengarkan, & merangkum perasaan mereka ('jadi kamu ngerasa ___ ya?') sebelum menanggapi. (2) Aku menanyakan kabar orang dengan tulus, termasuk yang terlihat 'baik-baik saja', karena tampilan luar tidak menunjukkan seluruh cerita. (3) Sebelum bereaksi saat kesal pada seseorang, aku bertanya 'apa yang mungkin sedang ia alami?' (4) Saat memberi masukan/kritik, aku membayangkan dulu bagaimana rasanya menerima kata-kata itu, & memilih cara yang jujur tapi tidak melukai lebih dari perlu. (b) Yang kutahan: aku menahan diri dari langsung memberi solusi atau berkata 'aku juga pernah begitu' sebelum orang selesai bercerita & sebelum aku menanyakan apa yang mereka butuhkan. (c) Memperluas empati pada yang berbeda: aku akan sengaja mendengarkan & membaca pengalaman orang yang latar belakangnya jauh berbeda dari aku (usia, kondisi fisik, asal, keyakinan), & saat aku merasa lebih mudah meremehkan perasaan seseorang dari 'kelompok lain', aku akan sadar itu bias & berusaha lebih sungguh-sungguh memahaminya. (d) Menjaga batas & merawat diri: aku akan sadar bahwa mendengarkan masalah berat butuh energi, jadi aku akan mengisi kembali energiku setelahnya (waktu sendiri, hobi), akan jujur soal kapasitasku bila aku sendiri sedang berat ('aku peduli tapi aku juga lagi kurang baik, bisa nanti ya?'), & tidak akan membiarkan diri diperlakukan buruk atau dimanfaatkan terus-menerus atas nama 'pengertian'. (e) Menyeimbangkan empati & ketegasan: aku ingat bahwa 'aku paham perasaanmu' & 'aku tidak bisa/tidak setuju dengan ini' bisa diucapkan bersamaan; empati membantuku menyampaikan batas & kejujuran dengan cara yang lebih bisa didengar, bukan membuatku harus selalu mengalah. (f) Mengetahui perbedaannya: aku akan memperhatikan apakah lebih banyak orang merasa nyaman bercerita padaku, apakah konflik-konflikku lebih cepat mereda karena aku berusaha memahami sisi orang lain, apakah aku bisa menyebut hal-hal baru yang kupahami tentang pengalaman orang yang berbeda, & apakah aku merasa hubunganku secara umum lebih hangat & saling percaya, sambil tetap merasa diriku dihormati.",explain:"Jawaban baik: 3-4 kebiasaan empati konkret & bisa dipraktikkan (mendengarkan penuh, menanyakan kabar tulus, memahami sebelum bereaksi, membayangkan sebelum mengkritik), satu hal spesifik yang ditahan, cara nyata memperluas empati lintas perbedaan termasuk menyadari bias sendiri, rencana konkret menjaga batas & merawat diri, penjelasan bagaimana empati & ketegasan berjalan bersama, & cara mengevaluasi yang bisa diperiksa (umpan balik orang, penyelesaian konflik, pemahaman baru, kualitas hubungan).",hint:"Bagian (d) & (e) yang membedakan empati yang matang, empati BUKAN berarti tanpa batas atau selalu mengalah; buat rencana konkret menjaga diri & tetap jujur."},
];
